fn affine(t:&[u64],s:&[u64],e:&[u64])->[u64;2]{let k=(1..s.len()).find(|&k|s[k]!=0).expect("generator_constant");let b=t.get(k).copied().unwrap_or(0)*power(s[k],629)%631;let a=(t.first().copied().unwrap_or(0)+631-b*s.first().copied().unwrap_or(0)%631)%631;assert_eq!(rem(&add(&[a],&scale(s,b),false),e),rem(t,e),"not_affine_in_generator");[a,b]}
fn main(){for label in ["D1","B-alt"]{let(e,x)=exact::checked(&format!("../hec_inverse631_20261116/generated-{label}/target.ms"),&format!("../hec_inverse631_20261116/solve-{label}.res"));assert_eq!(e.len(),13);let uv=ucoeff(&x,&e).expect("support_not_etale");assert_eq!(uv.len(),6);let s=&uv[0];let square=mm(s,s,&e);let [a,b]=affine(&square,s,&e);let q=vec![(631-a)%631,(631-b)%631,1];assert_eq!(gcd(q.clone(),deriv(&q)),vec![1]);let coefficients:Vec<_>=uv.iter().map(|t|affine(t,s,&e)).collect();let roots:Vec<_>=(0..631).filter(|&r|eval(&q,r)==0).collect();assert_eq!(roots.len(),2,"quadratic_not_split");for r in roots{let f=gcd(e.clone(),add(s,&[r],true));assert_eq!(f.len(),7,"permutation_fiber_not_six");let vals:Vec<_>=coefficients.iter().map(|c|(c[0]+c[1]*r)%631).collect();println!("DIVISOR label={label} generator={r} coefficients={vals:?} ordered_fiber_degree=6");}let mut bad=q.clone();bad[0]=(bad[0]+1)%631;let rel=add(&square,&add(&scale(s,q[1]),&[q[0]],false),false);assert!(rem(&rel,&e).is_empty());let badrel=add(&square,&add(&scale(s,bad[1]),&[bad[0]],false),false);assert!(!rem(&badrel,&e).is_empty());println!("QUADRATIC label={label} q={q:?} affine_coefficients={coefficients:?} exact_embedding=true corrupted_relation_rejected=true");}println!("PASS symmetric_inverse_algebras=2 ordered_degree=12 symmetric_degree=2 fiber_degree=6 direct_solver_or_speedup_verified=false");}
